import { useCallback, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar } from './data-table-toolbar';
import { columns } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { cn } from '@/lib/utils';
import { Attendances } from '../../types/attendances.types';

interface Props {
    className?: string;
    date?: string; // yyyy-MM-dd
}

export default function DepartureList({ className, date }: Props) {
    const [data, setData] = useState<Attendances[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    // Use useCallback to ensure the function reference is stable
    const fetchData = useCallback(async (options: FetchDataOptions) => {
        setIsLoading(true);
        try {
            const response = await apiGet({
                endpoint: endpoints.employee.attendance,
                queryParams: {
                    page: options.pageIndex + 1,
                    pageSize: options.pageSize,
                    ...(date ? { date } : {}),
                    ...options.filters,
                    search: options.globalFilter,
                },
            });

            setData(response.data.data.data);
            setPageCount(Math.ceil(response.data.data.pagination.total / options.pageSize));
            setTotalCount(response.data.data.pagination.total);
        } catch {
            // ignore; DataTable will show empty state
        } finally {
            setIsLoading(false);
        }
    }, [date]);

    return (
        <div
            className={cn(
                'mt-6 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]',
                className,
            )}
        >
            <DataTable
                key={date || 'today'}
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={DataTableToolbar}
                isLoading={isLoading}
                // cellPading={false}
            />
        </div>
    );
}
